-- creature_text
DELETE FROM `creature_text` WHERE `entry` IN (3843,24042,32859,32860,32863,32868,32888,32964,32970,32989,33043,33044,33079,33127,33176,33978,34033,34041,34046,34103,34340,34343,34413,34422,34423);
INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(3843,0,0,'The ages have been cruel to you and I, my love, but be assured, it is, and at long last we are reunited.',12,7,100.0,1,0,0,'Anaya'),
(3843,1,0,'Let it not trouble your heart, beloved. You have freed me from slavery, and for that I love you all the more.',12,7,100.0,1,0,0,'Anaya'),
(3843,2,0,'Sadly, even this must be cut short... The ties that bind me to this world weaken, and pull me away...',12,7,100.0,1,0,0,'Anaya'),
(3843,3,0,'Farewell, Cerellean, until we are joined once again...',12,7,100.0,1,0,0,'Anaya'),
(3843,4,0,'%s\'s soft voice trails away into the mists, \"Know that I love you always...\"',16,7,100.0,0,0,0,'Anaya'),
(24042,0,0,'$N\'s concoction is ruined.  A new one must be created from scratch.',16,0,100.0,0,0,0,'Generic Trigger LAB'),
(24042,1,0,'The failed concoction spills on the floor and appears to come to life!',16,0,100.0,0,0,0,'Generic Trigger LAB'),
(32859,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'combat Enrage'),
(32860,0,0,'Relax, mon, I be makin\' dis quick.',12,0,100.0,0,0,0,'on Aggro Text'),
(32863,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'combat Enrage'),
(32868,0,0,'Don\'t move, little adventurer. I have the death you seek.',12,0,100.0,0,0,0,'on Aggro Text'),
(32888,1,0,'Intruders! Good, I was getting bored...',12,0,50.0,0,0,0,'combat Text'),
(32888,1,1,'Masters, I pledge this Pin to you!',14,0,50.0,0,0,0,'combat Text'),
(32964,0,0,'Thanks for the rescue. Let\'s get out of here!',12,0,100.0,0,0,0,'Sentinel Aynasha'),
(32964,1,0,'Thanks for getting me out of there. I should be able to swim back from here, but before I go, one quick thing...',12,0,100.0,0,0,0,'Sentinel Aynasha'),
(32964,2,0,'I was afforded a brief chance to attack their leader, and he was protected by some kind of magic. Make sure Morra hears of this before leading any kind of attack.',12,0,100.0,0,0,0,'Sentinel Aynasha'),
(32964,3,0,'Farewell newcomer. May Elune\'s blessing be with you.',12,0,100.0,0,0,0,'Sentinel Aynasha'),
(32970,0,0,'A new victim! Me was almost don wit dis one anyway. ',12,0,100.0,0,0,0,'Rit\'ko'),
(32989,0,0,'Ya be messin\' with Tzu-Tzu? It no matter...Aetherion\'s here,mon.We gonna roll on ya refugee camp an\' then bring the hurt to ya Lor\'demal.But first ya die!',12,0,100.0,0,0,0,'on Aggro Text'),
(33043,0,0,'Thank you for saving me, stranger.',12,0,100.0,1,0,0,'Maddened Blackwood'),
(33044,0,0,'Thank you for saving me, stranger.',12,0,100.0,1,0,0,'Corrupted Blackwood'),
(33079,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'combat Enrage'),
(33127,0,0,'The moonstalker rouses from its slumber with a deep growl.',16,0,100.0,0,0,0,'Moonstalker'),
(33127,0,1,'The moonstalker wakes suddenly and lets out a low growl.',16,0,100.0,0,0,0,'Moonstalker'),
(33127,0,2,'The moonstalker jumps to its feet, teeth bared.',16,0,100.0,0,0,0,'Moonstalker'),
(33127,0,3,'The moonstalker rises, angry at being disturbed.',16,0,100.0,0,0,0,'Moonstalker'),
(33176,0,0,'And don\'t worry about the trolls underfoot while you\'re up there. They\'ll be trampled into the ground by the ancients\' strides.',12,0,100.0,0,0,0,'Kerlonian Evershade'),
(33978,0,0,'%s catches a fish!',16,0,100.0,0,0,0,'Hungry Thistle Bear'),
(34033,0,0,'Your flesh is forfeit!',12,0,100.0,15,0,0,'Teegan Holloway Aggro'),
(34033,1,0,'I said, SEARCH the bodies BEFORE you eat them!',12,0,100.0,5,0,0,'Teegan Holloway Script'),
(34033,1,1,'Leave no stone unturned. I mean that literally, you heaps of decay! Tear this place apart if you have to.',12,0,100.0,5,0,0,'Teegan Holloway Script'),
(34041,0,0,'What can you tell me, Keynira?',12,0,100.0,1,0,0,'Mathas Wildwood Script'),
(34041,1,0,'That will do for the moment. And the tower? What of Althalaxx?',12,0,100.0,273,0,0,'Mathas Wildwood Script'),
(34041,2,0,'That\'s all you\'ve got for me? I want numbers, locations, intentions - we\'re as good as blind. Get back out in the field!',12,0,100.0,5,0,0,'Mathas Wildwood Script'),
(34046,0,0,'%s cackles in glee.',16,0,100.0,0,0,0,'combat Text'),
(34103,0,0,'The catapults remain disabled. I\'ve burned several and trapped the others.',12,0,100.0,1,0,0,'Keynira Owlwing Script'),
(34103,1,0,'I - I don\'t know. There\'s movement in the ruins.',12,0,100.0,6,0,0,'Keynira Owlwing Script'),
(34340,0,0,'You big duffer, these ARE the same ruins. You\'re wandering in circles again.',12,0,100.0,0,0,0,'Archaeologist Groff'),
(34343,0,0,'Superb! Gather your strength, whats-your-face. We\'ve got a long way to travel.',12,0,100.0,4,0,0,'Prospector Remtravel'),
(34343,1,0,'Ready? Let\'s move!',12,0,100.0,0,0,0,'Prospector Remtravel'),
(34343,2,0,'The ruins you see here are identical to ones I dug up a few months ago, but they\'re flooded! Curious, eh?',12,0,100.0,1,0,0,'Prospector Remtravel'),
(34343,3,0,'Ah, we\'re almost there, whos-yer-face! The camp where I left my notes is just around the corner!',12,0,100.0,5,0,0,'Prospector Remtravel'),
(34343,4,0,'By the three hammers, will you look at that! More ruins!',12,0,100.0,25,0,0,'Prospector Remtravel'),
(34343,5,0,'These ruins I\'ve found are IDENTICAL to the ones I just left! It\'s the find of a lifetime!',12,0,100.0,0,0,0,'Prospector Remtravel'),
(34343,6,0,'Nonsense. See? Here\'s my journal, right here. ',12,0,100.0,1,0,0,'Prospector Remtravel'),
(34343,7,0,'What do you make of this, Ferd?',12,0,100.0,1,0,0,'Prospector Remtravel'),
(34413,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'combat Enrage'),
(34422,0,0,'It\'s over Azshara!  You and your naga will return to the bottom of the seas where you belong!',14,0,100.0,25,0,0,'Malfurion Stormrage'),
(34422,1,0,'She\'s not lying.  Nordrassil is in danger.  I must make haste and prepare for Hyjal\'s defense.',12,0,100.0,1,0,0,'Malfurion Stormrage'),
(34422,2,0,'It will be up to you to use the Horn of the Ancients and stop Soggoth\'s return.',12,0,100.0,0,0,0,'Malfurion Stormrage'),
(34423,0,0,'You are too late... the relic is being offered to Azshara above us as we speak!',12,0,100.0,0,0,0,'q13899');

