INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(32959,0,0,'Anaya...? Do my eyes deceive me? Is it really you?',12,7,100,1,0,0,'Cerellean Whiteclaw'),
(32959,1,0,'That the fates should be so cruel as to permit us only this after a thousand years apart...',12,7,100,1,0,0,'Cerellean Whiteclaw'),
(32959,2,0,'Do you hate me, my love? That I was forced to destroy your living form, that your spirit be released from unhappy bondage.',12,7,100,1,0,0,'Cerellean Whiteclaw'),
(32959,3,0,'No! Anaya... Anaya! Don''t leave me! Please...',12,7,100,5,0,0,'Cerellean Whiteclaw'),
(32959,4,0,'How, my love? How will I find the strength to face the ages of the world without you by my side...',12,7,100,5,0,0,'Cerellean Whiteclaw');
