INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(32869,0,0,'Company! Stay in sight, love, so that I can welcome you properly.',14,0,100,0,0,0,'Sheya Stormweaver'),
(32869,0,1,'Prey! Move away from those pillars so that I can show you the err in your trespass.',14,0,100,0,0,0,'Sheya Stormweaver'),
(32869,0,2,'Welcome! Don''t be shy... move away from those pillars so that I can see you fully.',14,0,100,0,0,0,'Sheya Stormweaver'),
(32869,0,3,'Hello there! Don''t you dare step behind those pillars. Let me welcome you properly.',14,0,100,0,0,0,'Sheya Stormweaver'),
(32868,0,0,'A challenge?! Stand still so that I can blast your corpse all over the ground.',14,0,100,0,0,0,'Lorenth Thundercall'),
(32868,0,1,'You think you can best Lorenth Thundercall? Stand still, silly gnat, so that I can swat you.',14,0,100,0,0,0,'Lorenth Thundercall'),
(32868,0,2,'Don''t move, little adventurer. I have the death you seek.',14,0,100,0,0,0,'Lorenth Thundercall'),
(32868,0,3,'Hah! Stay right there while I cast this spell! It won''t hurt much.',14,0,100,0,0,0,'Lorenth Thundercall');

