INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(32988,0,0,'Lor''danel is next, fool. With Aetherion almost completely in this world, it is only a matter of time!',12,0,100,0,0,0,'Cloudtamer Wildmane'),
(32988,0,1,'This place was only the beginning. We will crush your refugee camp and then lead our elementals north to destroy Lor''danel with Aetherion as our vanguard!',12,0,100,0,0,0,'Cloudtamer Wildmane'),
(32988,0,2,'Lor''danel must have been desperate to send you. We''ll deal with them soon enough!',12,0,100,0,0,0,'Cloudtamer Wildmane'),
(32989,0,0,'Whatcha doin'', mon? Don''tcha know the end o'' the world be nigh? Here, I show you!',12,0,100,0,0,0,'Windmaster Tzu-Tzu'),
(32989,0,1,'Ya be messin'' with Tzu-Tzu? It no matter... Aetherion''s here, mon. We gonna roll on ya refugee camp an'' then bring the hurt to ya Lor''denal. But first, ya die!',12,0,100,0,0,0,'Windmaster Tzu-Tzu'),
(32989,0,2,'Gots no time for playin'' with ya. Aetherion just about ready to go!',12,0,100,0,0,0,'Windmaster Tzu-Tzu'),
(32990,0,0,'Our master will break the world asunder and all that you know will come to an end. This is only a taste of what''s to come!',12,0,100,0,0,0,'Skylord Braax'),
(32990,0,1,'You will not stop our final ritual to bring Aetherion into the world. Too bad that you won''t live to see it!',12,0,100,0,0,0,'Skylord Braax'),
(32990,0,2,'If you only knew the power that I serve, you would not hesitate to kneel before me and join our ranks. Sadly, your ignorance will prove to be your undoing!',12,0,100,0,0,0,'Skylord Braax');

