INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(33041,0,0,'I HAVE ALMOST ARRIVED. TWILIGHT''S HAMMER, DO NOT RUSH THE SUMMONING OR I WILL DESTROY YOU AS WELL!',14,0,100,0,0,0,'Aetherion'),
(33041,0,1,'I SEE YOU, INSECT. RUN WHILE YOU CAN. RUN AND TELL YOUR PATHETIC LOR''DANEL THAT I AM COMING TO DESTROY IT!',14,0,100,0,0,0,'Aetherion'),
(33041,0,2,'MALFURION, CAN YOU HEAR ME?! WHEN I HAVE DESTROYED THE CHILDREN OF ELUNE, I WILL COME AND PUT AN END TO YOU!',14,0,100,0,0,0,'Aetherion'),
(33041,0,3,'MY MASTER COMES, MORTALS! I AM BUT ONE OF A LEGION OF HERALDS. YOUR WORLD IS ABOUT TO UNDERGO A TRANSFORMATION THAT WILL SEE THE END OF YOU!',14,0,100,0,0,0,'Aetherion'),
(33041,0,4,'PATIENCE! THE RITUAL TO BRING ME INTO THIS WORLD IS COMPLEX AND MUST NOT BE RUSHED!',14,0,100,0,0,0,'Aetherion'),
(33041,0,5,'JOIN THE TWILIGHT''S HAMMER NOW. THOSE WHO DO NOT BELONG WHEN I FULLY ENTER THE WORLD WILL KNOW ONLY DEATH!',14,0,100,0,0,0,'Aetherion'),
(33041,0,6,'THERE IS BUT ONE OUTCOME POSSIBLE. THE CATACLYSM WAS ONLY THE BEGINNING. THE WORLD AS YOU KNOW IT IS AT AN END!',14,0,100,0,0,0,'Aetherion'),
(33041,0,7,'YOU MORTALS ARE MADE OF THE STUFF OF THE ELEMENTS. HOW CAN YOU POSSIBLY HOPE TO PREVAIL? PREPARE TO RETURN TO YOUR TRUER, MORE BASIC NATURES!',14,0,100,0,0,0,'Aetherion'),
(33041,1,0,'YOU DARE?! TODAY WILL SEE THE END OF LOR''DANEL, MALFURION, AND YOU!',14,0,100,0,0,0,'Aetherion'),
(33041,2,0,'WHAT IS THIS? YALDA? AHAHAHAHAHA, THERE IS NOTHING THAT YOU OR THESE OTHER SPIRITS CAN DO TO STOP ME!',14,0,100,0,0,0,'Aetherion'),
(6887,0,0,'No, Aetherion, we will not allow that to happen!',12,0,100,0,0,0,'Yalda'),
(6887,1,0,'We shall see. Let us weaken him, my friends!',12,0,100,0,0,0,'Yalda'),
(33042,0,0,'EVEN IN THIS WEAKENED FORM, I WILL DESTROY YOU!!!',14,0,100,0,0,0,'Weakened Aetherion');

