DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=22 AND `SourceGroup`=1 AND `SourceEntry`=33232 AND `SourceId`=0;
INSERT INTO `conditions` (`SourceTypeOrReferenceId`,`SourceGroup`,`SourceEntry`,`SourceId`,`ElseGroup`,`ConditionTypeOrReference`,`ConditionTarget`,`ConditionValue1`,`ConditionValue2`,`ConditionValue3`,`NegativeCondition`,`ErrorType`,`ErrorTextId`,`ScriptName`,`Comment`) VALUES
(22,1,33232,0,0,30,1,194211,5,0,0,0,0,'','Archaeologist Hollee - Calls for help only while chained');
DELETE FROM `creature_text` WHERE `entry` IN (33232,33231);
INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(33232,0,0,'Hey! Anybody out there?',12,7,100,0,0,0,'Archaeologist Hollee (33371)'),
(33232,0,1,'Need some help here! Damsel in distress! <snort>',12,7,100,0,0,0,'Archaeologist Hollee (33372)'),
(33232,0,2,'Come to the top of the inn! They have me chained up!',12,7,100,0,0,0,'Archaeologist Hollee (33373)'),
(33232,0,3,'Somebody please! Get me out of here before they sacrifice me!',12,7,100,0,0,0,'Archaeologist Hollee (33374)'),
(33232,0,4,'Up here on the second floor of the inn! Hurry!',12,7,100,0,0,0,'Archaeologist Hollee (33375)'),
(33232,0,5,'Please! Someone! Anyone! Help me get out of here!',12,7,100,0,0,0,'Archaeologist Hollee (33376)'),
(33232,0,6,'You cultists are going to pay! Someone get me out of here!',12,7,100,0,0,0,'Archaeologist Hollee (33398)'),
(33232,0,7,'I am an archaeologist with the Explorers'' League! I can assure you that King Magni will hear of this outrage!',12,7,100,0,0,0,'Archaeologist Hollee (33399)'),
(33232,1,0,'Great! Let''s get out of here. I don''t have a weapon, so I''d really appreciate it if you could... you know... protect me?',12,7,100,0,0,0,'Archaeologist Hollee (33378)'),
(33232,2,0,'Let''s go.',12,7,100,0,0,0,'Archaeologist Hollee (33379)'),
(33232,3,0,'Taldan!',12,7,100,0,0,0,'Archaeologist Hollee (33402)'),
(33232,4,0,'This isn''t happening. Oh no... my friends!',12,7,100,0,0,0,'Archaeologist Hollee (33403)'),
(33232,5,0,'Hurry! We have to check on them!',12,7,100,0,0,0,'Archaeologist Hollee (33404)'),
(33232,6,0,'It''s trashed, but it doesn''t look like there are any bodies.',12,7,100,0,0,0,'Archaeologist Hollee (33405)'),
(33232,7,0,'Sorry, but I had to check. Okay, let''s get out of here.',12,7,100,0,0,0,'Archaeologist Hollee (33406)'),
(33232,8,0,'There''s the refugee camp!',12,7,100,0,0,0,'Archaeologist Hollee (33380)'),
(33232,9,0,'I''ll race you!',12,7,100,0,0,0,'Archaeologist Hollee (33381)'),
(33232,10,0,'Elisa! Oh, it''s so good to get out of there! Auberdine is completely overrun with cultists and elementals!',12,7,100,0,0,0,'Archaeologist Hollee (33383)'),
(33232,11,0,'I have a favor to ask. Could you reward my friend here? I haven''t any coin. I can pay you when we get back to Ironforge.',12,7,100,0,0,0,'Archaeologist Hollee (33386)'),
(33232,12,0,'Oh, thank you, Elisa! Thank you!',12,7,100,0,0,0,'Archaeologist Hollee (33388)'),
(33232,13,0,'Time for a very short breather.',12,7,100,0,0,0,'Archaeologist Hollee (33390)'),
(33232,13,1,'We have to get out of here.',12,7,100,0,0,0,'Archaeologist Hollee (33391)'),
(33232,13,2,'How many elementals do they have?!',12,7,100,0,0,0,'Archaeologist Hollee (33392)'),
(33232,13,3,'This has to be said... the Twilight''s Hammer sucks!',12,7,100,0,0,0,'Archaeologist Hollee (33393)'),
(33232,13,4,'That was the last one, right?',12,7,100,0,0,0,'Archaeologist Hollee (33394)'),
(33232,13,5,'Why did I ever let Remtravel convince me to come to Darkshore?!',12,7,100,0,0,0,'Archaeologist Hollee (33395)'),
(33232,13,6,'I''d be dead if it weren''t for you.',12,7,100,0,0,0,'Archaeologist Hollee (33396)'),
(33232,13,7,'This would never have happened to Ironforge!',12,7,100,0,0,0,'Archaeologist Hollee (33397)'),
(33231,0,0,'Hollee!',12,7,100,0,0,0,'Elisa Steelhand (33382)'),
(33231,1,0,'I know, lass, but you''re safe now and with friends. I thought you were dead!',12,7,100,0,0,0,'Elisa Steelhand (33384)'),
(33231,2,0,'Of course. Don''t think anything of it. And I won''t hear of you trying to pay me back, either!',12,7,100,0,0,0,'Elisa Steelhand (33387)'),
(33231,3,0,'Anytime, lass. Anytime.',12,7,100,0,0,0,'Elisa Steelhand (33389)');

-- Twilight Rider (34282) is the flying vehicle. The humanoid (34293) is its passenger,
-- so the separate humanoid spawns are removed. InhabitType 4 keeps both in the air.
UPDATE `creature_template` SET `InhabitType`=4 WHERE `entry` IN (34282, 34293);
DELETE FROM `creature` WHERE `guid` IN (188995, 188996, 188997, 188998, 188999, 189000, 189001);

-- Soothing Totem (44959, spell 62430) absorbs one dead Unbound Fire Elemental (32999).
-- The spellhit script marks that corpse by setting its event phase to 1.
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=17 AND `SourceEntry`=62430;
INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES
(17, 0, 62430, 0, 0, 31, 1, 3, 32999, 0, 0, 0, 0, '', 'Soothing Totem - target is an Unbound Fire Elemental'),
(17, 0, 62430, 0, 0, 36, 1, 0, 0, 0, 1, 0, 0, '', 'Soothing Totem - target is dead'),
(17, 0, 62430, 0, 0, 101, 1, 1, 0, 0, 1, 0, 0, '', 'Soothing Totem - corpse has not already been absorbed');

-- Quest 13580. The energized totem is level 14 and stays up while remnants, then a rager, attack it.
-- Credit is given by the totem script when the rager dies, not by the old timer.
UPDATE `creature_template` SET `minlevel`=14, `maxlevel`=14, `Health_mod`=5, `ScriptName`='npc_darkshore_soothing_totem' WHERE `entry`=34367;
UPDATE `smart_scripts` SET `target_type`=19, `target_param1`=34367, `target_param2`=40, `comment`='Fire Elemental Remnant - attack the soothing totem' WHERE `entryorguid`=34368 AND `source_type`=0 AND `id`=0 AND `event_type`=54;
UPDATE `smart_scripts` SET `target_type`=19, `target_param1`=34367, `target_param2`=40, `comment`='Fire Elemental Rager - attack the soothing totem' WHERE `entryorguid`=34370 AND `source_type`=0 AND `id`=0 AND `event_type`=54;
DELETE FROM `smart_scripts` WHERE `entryorguid`=34371 AND `source_type`=0;
DELETE FROM `smart_scripts` WHERE `entryorguid`=3436700 AND `source_type`=9;
DELETE FROM `creature_text` WHERE `entry`=34367;
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(34367, 0, 0, 'The Ritual of Soothing has begun. Defend the totem at all costs!', 42, 0, 100, 0, 0, 0, 'Energized Soothing Totem - ritual started'),
(34367, 1, 0, 'The Ritual of Soothing has completed.', 42, 0, 100, 0, 0, 0, 'Energized Soothing Totem - ritual completed');
UPDATE `smart_scripts` SET `action_param1`=4000 WHERE `entryorguid`=34370 AND `source_type`=0 AND `event_type`=6 AND `action_type`=41;

