-- Stepping Up Surveillance (13948): up on the platform Doomspeaker Trevellion and Thalya the Voidcaller
-- discuss the ritual when a disguised spy sneaks up; listening in gives the surveillance credit.
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_doomspeaker_trevellion' WHERE `entry`=34326;
DELETE FROM `creature_text` WHERE `entry` IN (34326, 34405, 34406, 34427);
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(34405, 0, 0, 'Why are we digging this thing up anyway, boss?', 12, 0, 100, 6, 0, 0, 'Twilight Worker - Leave No Tracks'),
(34406, 0, 0, 'Watch your tongue, worm.  You will not refer to Soggoth the Slitherer as "that thing" or you''ll find yourself eating your own heart for dinner.', 12, 0, 100, 1, 0, 0, 'Foreman Balsoth - Leave No Tracks 1'),
(34406, 1, 0, 'Now, back to work!  Your superiors are watching from the outlook above and they do not take kindly to idleness!', 12, 0, 100, 5, 0, 0, 'Foreman Balsoth - Leave No Tracks 2'),
(34326, 0, 0, 'Our men are almost finished unearthing great Soggoth.  Is the ritual ready?', 12, 0, 100, 1, 0, 0, 'Doomspeaker Trevellion - Stepping Up Surveillance 1'),
(34326, 1, 0, 'Do not worry.  Like I said, our men are almost done unearthing the Slithering One.  They will make for a suitable -- and even voluntary -- sacrifice.  Soggoth will rise!', 12, 0, 100, 1, 0, 0, 'Doomspeaker Trevellion - Stepping Up Surveillance 2'),
(34427, 0, 0, 'Not quite.  We shall need a great many offerings of sacrifice before the Herald of the Old Gods roams the land again.', 12, 0, 100, 1, 0, 0, 'Thalya the Voidcaller - Stepping Up Surveillance');

