INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(34376, 0, 0, 'Hold on tight! I''ll take care of the flying, you focus on the wildlife below.', 12, 0, 100, 0, 0, 0, 'Kathrena Winterwisp - In Defense of Darkshore takeoff'),
(34376, 1, 0, 'From the air, you should be able to cast your protective ward on whole groups of animals at once.', 12, 0, 100, 0, 0, 0, 'Kathrena Winterwisp - In Defense of Darkshore ward'),
(34376, 2, 0, 'Whitetail deer have been repopulating this whole area.', 12, 0, 100, 0, 0, 0, 'Kathrena Winterwisp - In Defense of Darkshore deer'),
(34376, 3, 0, 'Moonstalkers displaced by the fires patrol this strand, we need to keep them safe!', 12, 0, 100, 0, 0, 0, 'Kathrena Winterwisp - In Defense of Darkshore moonstalkers'),
(34376, 4, 0, 'Hold on, the updraft from the fires can be fierce.', 12, 0, 100, 0, 0, 0, 'Kathrena Winterwisp - In Defense of Darkshore updraft'),
(34376, 5, 0, 'Look below - some of those thistle bears haven''t been consumed yet. We''re not too late.', 12, 0, 100, 0, 0, 0, 'Kathrena Winterwisp - In Defense of Darkshore bears'),
(34376, 6, 0, 'Why would anyone want to dig up something so horrific? I''m convinced those things are behind what''s happening to the animals here.', 12, 0, 100, 0, 0, 0, 'Kathrena Winterwisp - In Defense of Darkshore dig site'),
(34376, 7, 0, 'Good work! Let Orseus know if we need to take another pass. Otherwise, I''ll meet you in the grove!', 12, 0, 100, 0, 0, 0, 'Kathrena Winterwisp - In Defense of Darkshore landing');

-- The Devourer of Darkshore (13891): planting the Lifebringer Sapling at the Consumed Watering Hole raises
-- Yoth'al the Devourer. The watering hole is only the sapling's spell focus, so it has no model; its
-- range covers the pool's edge. A trigger on the pool surface churns the water (Roiling Seas) while
-- Yoth'al rises; a few seconds later he grows (Awoken) and fights from his spot, and Awoken fades when
-- he dies. The sapling's
-- Threaten Yoth'al pulse only threatens him, not every creature around the pool.
