-- The Offering to Azshara (13900): when the last Darkscale Priestess above Nazj'vel falls, Queen Azshara
-- appears at the altar, Malfurion arrives to drive her off and the offering counts as prevented. The
-- Malfurion standing above Nazj'vel only shows once the offering has been stopped.
UPDATE `creature_template` SET `faction_A`=74, `faction_H`=74, `unit_flags`=33024, `flags_extra`=2, `AIName`='SmartAI' WHERE `entry`=34416;
DELETE FROM `creature_text` WHERE `entry`=34416;
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(34416, 0, 0, 'Who dares oppose Queen Azshara?  You will soon beg for a swift death!', 14, 0, 100, 1, 0, 0, 'Queen Azshara - The Offering to Azshara 1'),
(34416, 1, 0, 'Ah... Malfurion Stormrage.  I''d hoped to keep you occupied for a little longer.  It was my goal to keep you away from Hyjal while my allies attacked.  It would seem I have succeeded.', 12, 0, 100, 1, 0, 0, 'Queen Azshara - The Offering to Azshara 2'),
(34416, 2, 0, 'I''ve no need to fight you, for it appears I''ve already won.  You cannot stop our attack on Darkshore and save Hyjal at the same time!', 12, 0, 100, 1, 0, 0, 'Queen Azshara - The Offering to Azshara 3');
