-- Quests finished by a script or area trigger (Timely Arrival, Consumed, The Darkscale Warlord, The
-- Absent-Minded Prospector) must not complete as soon as they are accepted.
UPDATE `quest_template` SET `SpecialFlags`=`SpecialFlags`|2 WHERE `Id` IN (13510,13881,13899,13911);

